import { spawn, spawnSync } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import {
  closeSync,
  existsSync,
  fsyncSync,
  linkSync,
  lstatSync,
  mkdirSync,
  openSync,
  readFileSync,
  realpathSync,
  rmSync,
  statfsSync,
  writeFileSync,
} from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const header =
  '# Generated by scripts/amc-agent.mjs from data/amc/agent-definitions.json\n';
export function definitions() {
  const value = JSON.parse(
    readFileSync(join(root, 'data/amc/agent-definitions.json'), 'utf8'),
  );
  if (
    value.schema !== 'amc-agents/1' ||
    !Array.isArray(value.agents) ||
    value.agents.length !== 3
  )
    throw new Error('Invalid AMC agent definitions');
  const names = new Set();
  for (const agent of value.agents) {
    if (
      !/^[a-z][a-z-]+$/.test(agent.name) ||
      names.has(agent.name) ||
      !agent.description?.trim() ||
      !agent.developer_instructions?.trim()
    )
      throw new Error('Invalid AMC agent');
    if (
      Object.keys(agent).some(
        (k) =>
          ![
            'name',
            'description',
            'developer_instructions',
            'sandbox_mode',
          ].includes(k),
      )
    )
      throw new Error('Unexpected AMC agent setting');
    if (agent.sandbox_mode !== undefined && agent.sandbox_mode !== 'read-only')
      throw new Error('AMC agent cannot expand sandbox permissions');
    names.add(agent.name);
  }
  if (!['amc', 'amc-worker', 'amc-reviewer'].every((n) => names.has(n)))
    throw new Error('Missing AMC role');
  return value.agents;
}
export function renderAgent(agent) {
  // JSON basic strings are valid TOML strings for this controlled text registry.
  return (
    header +
    Object.entries(agent)
      .map(([k, v]) => `${k} = ${JSON.stringify(v)}`)
      .join('\n') +
    '\n'
  );
}
function regularDirectory(path) {
  const info = lstatSync(path, { throwIfNoEntry: false });
  if (info && (!info.isDirectory() || info.isSymbolicLink()))
    throw new Error('Refusing unsafe agent directory: ' + path);
}
function registrationDirectories(target) {
  return ['.codex', '.codex/agents', '.agents', '.agents/skills', '.agents/skills/amc']
    .map((path) => join(target, path));
}

// Never publish a partial definition. link() is atomic and refuses an existing
// destination, including one created by another installer after our preflight.
export function atomicCreate(path, text, write = writeFileSync) {
  const temporary = join(dirname(path), `.amc-${randomUUID()}.tmp`);
  const fd = openSync(temporary, 'wx', 0o600);
  let closed = false;
  try {
    write(fd, text);
    fsyncSync(fd);
    closeSync(fd);
    closed = true;
    linkSync(temporary, path);
  } finally {
    try { if (!closed) closeSync(fd); }
    finally { rmSync(temporary); }
  }
}
export function installAgents(project = root) {
  const target = realpathSync(project);
  const config = join(target, '.codex'),
    directory = join(config, 'agents');
  const skillDirectory = join(target, '.agents', 'skills', 'amc');
  for (const path of registrationDirectories(target))
    regularDirectory(path);
  const entries = definitions().map((a) => ({
    path: join(directory, a.name + '.toml'),
    text: renderAgent(a),
  }));
  entries.push({
    path: join(skillDirectory, 'SKILL.md'),
    text: readFileSync(join(root, 'toolkits/amc-agent/SKILL.md'), 'utf8'),
  });
  // Inspect every destination before writing any; preserve unrelated/custom files.
  for (const entry of entries)
    if (lstatSync(entry.path, { throwIfNoEntry: false })) {
      if (
        !lstatSync(entry.path).isFile() ||
        lstatSync(entry.path).isSymbolicLink() ||
        readFileSync(entry.path, 'utf8') !== entry.text
      )
        throw new Error(
          '既存のエージェント定義を保持します。差分を確認してください: ' +
            entry.path,
        );
    }
  mkdirSync(directory, { recursive: true });
  mkdirSync(skillDirectory, { recursive: true });
  for (const entry of entries)
    if (!existsSync(entry.path))
      atomicCreate(entry.path, entry.text);
  return entries.filter((e) => e.path.endsWith('.toml')).map((e) => e.path);
}
export const usage = `AMC — このチャットで「AMCで、やりたいことを進めて」と依頼できます。
スキル選択では $amc を指定します。Web画面や別CLIの起動は不要です。

端末から使う場合:
  npm run amc -- "やりたいこと"       Codexを起動
  npm run amc -- doctor               設定・空き容量を確認（変更なし）
  npm run amc -- install              このプロジェクトへ登録
  npm run amc -- run --goal "依頼" --preview  送信せず起動内容を確認
`;

export function diagnose(project = root, {
  probeCli = () => spawnSync('codex', ['--version'], { encoding: 'utf8', timeout: 5000 }),
  freeBytes = (path) => { const s = statfsSync(path); return s.bavail * s.bsize; },
} = {}) {
  const target = realpathSync(project);
  const expected = definitions().map((a) => ({ path: `.codex/agents/${a.name}.toml`, text: renderAgent(a) }));
  expected.push({ path: '.agents/skills/amc/SKILL.md', text: readFileSync(join(root, 'toolkits/amc-agent/SKILL.md'), 'utf8') });
  const checks = [];
  for (const path of registrationDirectories(target)) {
    try { regularDirectory(path); }
    catch { checks.push({ code: 'unsafe_directory', path, status: 'error', message: '登録先の親フォルダが通常のディレクトリではありません。リンクや既存ファイルを確認してください。自動変更はしません。' }); }
  }
  checks.push(...expected.map(({ path, text }) => {
    try {
      const full = join(target, path);
      const valid = lstatSync(full).isFile() && readFileSync(full, 'utf8') === text;
      return { code: 'definition', path, status: valid ? 'ok' : 'error', message: valid ? '登録済み' : '既存定義に差分があります。内容を確認してから更新してください。' };
    } catch { return { code: 'definition', path, status: 'error', message: '未登録です。npm run amc -- install で登録できます。' }; }
  }));
  const cli = probeCli();
  checks.push({ code: 'cli', status: cli.status === 0 ? 'ok' : 'warning', message: cli.status === 0 ? '端末版Codexを利用できます（認証・実行の検証ではありません）。' : '端末版Codexを確認できません。このチャットではAMCを利用できます。' });
  for (const [code, path] of [['project_space', target], ['temporary_space', tmpdir()]]) {
    try {
      const bytes = freeBytes(path);
      checks.push({ code, path, availableMiB: Math.floor(bytes / 1048576), status: bytes < 512 * 1048576 ? 'warning' : 'ok', message: bytes < 512 * 1048576 ? '空き容量が512MiB未満です。大きなbuildや保存の前に不要なファイルを確認してください。自動削除はしません。' : '空き容量を確認しました。' });
    } catch { checks.push({ code, path, status: 'warning', message: '空き容量を取得できませんでした。OSのストレージ設定で確認してください。' }); }
  }
  return { ready: checks.every((c) => c.status !== 'error'), checks, invocation: 'AMCで、やりたいことを進めて', webSync: false };
}

export function friendlyError(error) {
  if (['ENOSPC', 'SQLITE_FULL'].includes(error.code) || /SQLITE_FULL/.test(error.message))
    return '保存先の空き容量が不足しています。入力を保持し、OSのストレージ設定で空きを確保してから再試行してください。';
  if (error.code === 'ENOENT') return '必要なファイルまたはCodex CLIが見つかりません。npm run amc -- doctor で確認するか、このチャットで「AMCで…」と依頼してください。';
  if (error.code === 'EACCES' || error.code === 'EPERM') return '設定先へのアクセスが許可されていません。権限を確認してください。既存の保護設定は変更していません。';
  return error.message;
}
export function launchArgs({ goal, repo = root }) {
  if (typeof goal !== 'string' || !goal.trim() || goal.length > 16000)
    throw new Error('Goalは1〜16000文字で指定してください。');
  const agents = definitions();
  const instruction = agents.find(
    (a) => a.name === 'amc',
  ).developer_instructions;
  return [
    '--cd',
    realpathSync(repo),
    '-c',
    'developer_instructions=' + JSON.stringify(instruction),
    'AMCとして次の依頼を遂行してください。独立した任務は利用可能な範囲で並列部隊へ割り当て、Goalと意図を維持してください。\n\n利用者のGoal:\n' +
      goal.trim(),
  ];
}
export function parseArgs(args) {
  if (!args.length || ['help', '--help', '-h'].includes(args[0])) return { command: 'help' };
  const [command, ...rest] = args;
  if (!['describe', 'install', 'run', 'doctor'].includes(command)) {
    if (args.length === 1 && !command.startsWith('-')) return { command: 'run', goal: command };
    throw new Error('依頼文は引用符で囲んでください。例: npm run amc -- "作りたいもの"');
  }
  const options = { command };
  for (let i = 0; i < rest.length; i++) {
    const flag = rest[i];
    if (flag === '--preview' && command === 'run' && !options.preview) {
      options.preview = true;
      continue;
    }
    if (
      !['--project', '--goal'].includes(flag) ||
      !rest[i + 1] ||
      rest[i + 1].startsWith('--')
    )
      throw new Error('Unknown or incomplete option: ' + flag);
    const key = flag.slice(2);
    if (options[key]) throw new Error('Duplicate option: ' + flag);
    options[key] = rest[++i];
  }
  if (command !== 'run' && options.goal) throw new Error('--goal requires run');
  if (command === 'describe' && options.project)
    throw new Error('--project requires install or run');
  return options;
}
export async function main(args = process.argv.slice(2)) {
  const options = parseArgs(args);
  if (options.command === 'help') { console.log(usage); return; }
  if (options.command === 'doctor') {
    const report = diagnose(options.project ?? root);
    for (const check of report.checks) console.log(`${check.status === 'ok' ? '✓' : check.status === 'warning' ? '注意' : '要対応'} ${check.path ?? check.code}: ${check.message}${check.availableMiB === undefined ? '' : ` (${check.availableMiB}MiB)`}`);
    console.log(`\n呼び出し: ${report.invocation}\nWebへの自動同期は未接続です。`);
    if (!report.ready) process.exitCode = 1;
    return;
  }
  if (options.command === 'describe') {
    console.log(
      JSON.stringify(
        {
          agents: definitions().map((a) => ({
            name: a.name,
            description: a.description,
          })),
          invoke: 'AMCで「達成したいGoal」を進めて',
          execution: 'Codex session; Web start/sync not connected',
          model: 'custom agents inherit parent; launcher uses existing CLI settings',
        },
        null,
        2,
      ),
    );
    return;
  }
  if (options.command === 'install') {
    console.log(
      JSON.stringify(
        { installed: installAgents(options.project ?? root), skill: '.agents/skills/amc/SKILL.md', started: false },
        null,
        2,
      ),
    );
    return;
  }
  const repo = options.project ?? root;
  const argv = launchArgs({ goal: options.goal, repo });
  if (options.preview) {
    console.log(
      JSON.stringify({ command: 'codex', args: argv, started: false }, null, 2),
    );
    return;
  }
  if (!process.stdin.isTTY || !process.stdout.isTTY)
    throw new Error('この起動口は対話端末用です。Codexのチャット内では「AMCで、依頼内容を進めて」と伝えてください。起動内容の確認は --preview を使えます。');
  // User starts this command explicitly; inherit terminal auth/model/approval.
  // No shell interpolation, no approval bypass, no scheduled/background launch.
  installAgents(repo);
  const child = spawn('codex', argv, { stdio: 'inherit', shell: false });
  await new Promise((resolveRun, reject) => {
    child.once('error', reject);
    child.once('exit', (code, signal) => {
      process.exitCode = code ?? (signal ? 130 : 1);
      resolveRun();
    });
  });
}
if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
)
  main().catch((error) => {
    console.error(friendlyError(error));
    process.exitCode = 1;
  });
